B.buI=new A.O("Leggi",null,null,null,null,null,null,null,null,null)
B.buJ=new A.O("Ho letto la dichiarazione di responsabilit\xe0 e me la assumo per questa Gazzettina.",null,null,null,null,null,null,null,null,null)
B.buK=new A.O("Non \xe8 questa persona",null,null,null,null,null,null,null,null,null)
B.buL=new A.O("Con una squadra under 18 la Gazzettina celebra e non prende in giro: il cursore del tono arriva al massimo a 5, ogni ragazzo che ha giocato viene nominato almeno una volta, e le caratteristiche private non si usano. Si salva solo l'anno di nascita.",null,B.M,null,null,null,null,null,null,null)
B.Zu=new A.O("Cancella per sempre",null,null,null,null,null,null,null,null,null)
B.buN=new A.O("Controlla, togli la spunta a quelle che non vuoi e salva. Dopo puoi correggere ogni partita dalla sua pagina.",null,B.M,null,null,null,null,null,null,null)
B.buO=new A.O("Dichiarazione di responsabilit\xe0",null,null,null,null,null,null,null,null,null)
B.buQ=new A.O("Sei uno dei giocatori di questo campionato? Apri una giornata e tocca \xabSono io\xbb accanto al tuo nome: l'organizzatore conferma e la scheda diventa tua.",null,B.M,null,null,null,null,null,null,null)
B.fn=new A.O("Salva",null,null,null,null,null,null,null,null,null)
